There exists a real number $D>0$ such that for sufficiently close $\theta, \theta' \in \mathcal{J}$: 
\begin{equation} 
\| P_{\theta} - P_{\theta'}\|_1 \leq D|\theta - \theta'|. 
\end{equation} and there exists an open interval $\mathcal{I}$ such that 
\begin{equation} 
p_{0,\mathcal{I}} := \inf_{\theta \in \mathcal{I}} \min_{x \in \mathcal{X}} P_\theta(x) >0.
\end{equation}
\par\hangindent 40\p@

There exists a real number $F>0$ such that for $\theta, \theta' \in \mathcal{J}$, if $P_\theta$ and $P_{\theta'}$ are sufficiently close: 
\begin{equation} 
\| P_{\theta} - P_{\theta'}\|_1 \geq F |\theta - \theta'|. 
\end{equation} 
\end{itemize} 
Our main result are  upper and lower bounds on    $R_{n,k}^\star$ under above assumptions. Notice that these assumptions are in particular satisfied for the canonical problem of $P_{\theta}$ the Bernoulli-$\theta$ distribution and $\mathcal{J}=[0,1]$.
\begin{theorem}[Converse]\label{thm:1}
Under above Assumption~1, 
 for sufficiently large values of $n$:
\begin{equation} 
C_{\textnormal{lower}} \cdot \frac{ 1}{n k^{2}} \leq   R_{n,k}^\star,
\end{equation} 
where 
\begin{equation}
C_{\textnormal{lower}} = \frac14(m-1)^{1-m} e^{-\frac{(1+D)^2}{p_{0,\mathcal{I}}}-1}m^{\frac m2}\frac1{(2\pi)^{\frac{m-1}2}}.
\end{equation}
\end{theorem}

\label{thm:1}
Under above Assumption~1, 
 for sufficiently large values of $n$:
\begin{equation} 
C_{\textnormal{lower}} \cdot \frac{ 1}{n k^{2}} \leq   R_{n,k}^\star,
\end{equation} 
where 
\begin{equation}
C_{\textnormal{lower}} = \frac14(m-1)^{1-m} e^{-\frac{(1+D)^2}{p_{0,\mathcal{I}}}-1}m^{\frac m2}\frac1{(2\pi)^{\frac{m-1}2}}.
\end{equation}

\label{thm:2}
Under Assumptions~1 and 2, if $k>\frac{D+F}{2F}$ and for $n$ large enough:
\begin{equation}\label{eq:U1}
   R_{n,k}^\star  \leq \frac{8m|\mathcal J|^2}{nk^2}+\frac{m^2\ln(nk^2)}{n\left((k-1/2)F-D/2\right)^2}.
\end{equation}


Moreover, if $\mathcal{J}=[0,1]$ and $P_\theta$ is Bernoulli-$\theta$, then  for $k>2$:
\begin{equation}\label{eq:U2}
   R_{n,k}^\star  \leq \frac{321\ln(k^2)}{n(k/2-1)^{2}} .
\end{equation}

\label{lemma1}
\begin{enumerate}
\par\hangindent 40\p@ For sufficiently large $n$, the number of $n$-types in  region $\mathcal{R}_{\mathcal{I}}$ is \begin{equation}
    |\mathcal{R}_{\mathcal{I}} | \geq  (m-1)^{-(m-1)}\cdot \sqrt n^{m-1}.
\end{equation}
\par\hangindent 40\p@ For all $\theta'\in \mathcal{I}$ and $\boldsymbol{\pi} \in \mathcal{R}_{\mathcal{I}}$:
    \begin{equation}
         P_{\theta'}(\boldsymbol{\pi})\geq \frac{C}{\sqrt{n}^{m-1}}=:P_{\min} ,
    \end{equation}
    where $C=e^{-(1+D)^2 /p_0-1}m^{\frac m2}\frac1{(2\pi)^{\frac{m-1}2}}$






\end{enumerate}

By definition of  $\mathcal{R}_{\mathcal{I}}$:  
\begin{equation}
    \mathbb{B}_{P_{{\theta}'}}\left(\frac1{\sqrt n}\right) \subseteq \mathcal{R}_{\mathcal{I}}                                                                           
    \label{eq:balls}
\end{equation}
Moreover, by Assumption \eqref{eq:p0}, 

for sufficiently large $n$, the number of $n$-types in   ball $\mathbb{B}_{P_{\theta'}}\left(r\right)$ is  lower bounded by $(r/(m-1))^{m-1}$. Setting $r=n^{-1/2}$, this concludes the proof of 1).

For any $\theta \in \mathcal{I}$ and type $\boldsymbol{\pi} \in \mathcal{R}_I$: 
\begin{equation}  P_{\theta}(\boldsymbol{\pi}) = \begin{pmatrix}
        n \\ n \boldsymbol{\pi}(1),...,n\boldsymbol{\pi}(m)
    \end{pmatrix}\prod_{i\in \mathcal{X}}P_{\theta}(i) ^{n\boldsymbol{\pi}(i)}.\end{equation}
    We use Stirling's  and Herbert Robbins' bounds to write
    \begin{equation}
        e^{\frac1{12n+1}}\frac{n^n}{e^n}\sqrt{2\pi n}<n!<e^{\frac1{12n}}\frac{n^n}{e^n}\sqrt{2\pi n}
    \end{equation}
 and thus to conclude:
    \begin{align}
        P_{\theta}(\boldsymbol{\pi}) &\geq \frac{e^{\frac1{12 n+1}}}{\prod_{i=1}^me^{\frac1{12 n\boldsymbol{\pi}(i)}}}\cdot \frac{ n^ n}{\prod_{i=1}^m ( n\boldsymbol{\pi}(i))^{ n\boldsymbol{\pi}(i)}} \nonumber \\
        &\qquad \cdot  \frac{\sqrt{2\pi  n}}{\prod_{i=1}^m\sqrt{2\pi  n\boldsymbol{\pi}(i)}}\prod_{i=1}^mP_{\theta}(i) ^{n\boldsymbol{\pi}(i)} \\
        &\geq \frac{e^{\frac1{12 n+1}}}{ e^{\frac{m}{12 (np_0-\sqrt{n})}}}\cdot \frac{1}{\prod_{i=1}^m \left(\frac{ \boldsymbol{\pi}(i)}{ P_{\theta}(i)}\right)^{ n \boldsymbol{\pi}(i)}} \nonumber \\
        & \qquad \cdot \frac{1}{\sqrt{2\pi}^{m-1}}\cdot \sqrt{\frac{ n}{\prod_{i=1}^m n \boldsymbol{\pi}(i)}}
    \end{align}
where we used that  $\sum_i \boldsymbol{\pi}(i) = 1$ and 
\begin{equation} 
\frac{e^{\frac1{12 n+1}}}{\prod_{i=1}^me^{\frac1{12 n\boldsymbol{\pi}_i}}} \geq \frac{e^{\frac1{12 n+1}}}{ e^{\frac{m}{12 (np_0-\sqrt{n})}}}
.
\end{equation} 






Moreover,  since the geometric mean is upper bounded by the arithmetic mean, 
\begin{equation} \prod_{i=1}^m \boldsymbol{\pi}(i)\leq \left(\frac{\sum_{i=1}^m \boldsymbol{\pi}(i)}{m}\right)^m = m^{-m} \end{equation} and thus :
    \begin{equation}
        \sqrt{\frac{ n}{\prod_{i=1}^m n \boldsymbol{\pi}(i)}} \geq  n^{-\frac{m-1}2} m^{\frac m2}.
    \end{equation}
    By the triangle inequality and Assumption 1,                                                             
    we  have for any $\theta\in \mathcal{I}$ and $\boldsymbol{\pi} \in \mathcal{R}_{\mathcal{I}}$:
\begin{IEEEeqnarray}{rCl}
\| {\boldsymbol{\pi}} - P_{{\theta}} \|_1 & \leq &\| {\boldsymbol{\pi}} - P_{\theta'} \|_1 +\|  P_{\theta'} -P_{{\theta}} \|_1\\
& \leq &
 \frac{1}{\sqrt{n}} + D| \theta' -{\theta}| \\
 & \leq&  \frac{1+ D }{\sqrt{n}},\label{eq:bound}
 \end{IEEEeqnarray}
 where $\theta'$ is the parameter so that $\boldsymbol{\pi} \in \mathbb{B}_{P_{\theta'}}\left(1/\sqrt{n}\right)$. 





 We therefore have:   \begin{IEEEeqnarray}{l}
       \lefteqn{ \log \left(\prod_{i=1}^m \left(\frac{ \boldsymbol{\pi}(i)}{ P_{\theta}(i)}\right)^{ n \boldsymbol{\pi}(i)}\right) } \nonumber \\=\sum_{i=1}^m  n \boldsymbol{\pi}(i) \log\left(\frac{ \boldsymbol{\pi}(i)}{ P_{\theta}(i)}\right)\\
         = \sum_{i=1}^m  n \boldsymbol{\pi}(i) \log\left(1+\frac{ \boldsymbol{\pi}(i)- P_{\theta}(i)}{ P_{\theta}(i)}\right)\\
        \leq \sum_{i=1}^m  n(( \boldsymbol{\pi}(i)- P_{\theta}(i))+ P_{\theta}(i))\frac{ \boldsymbol{\pi}(i)- P_{\theta}(i)}{ P_{\theta}(i)}\\
         =  n\sum_{i=1}^m( \boldsymbol{\pi}(i)- P_{\theta}(i)) +  n\sum_{i=1}^m\frac{( \boldsymbol{\pi}(i) - P_{\theta}(i))^2}{ P_{\theta}(i)}\\
        \leq 0+ (1+ D)^2  /p_0.
    \end{IEEEeqnarray}


    Combining above observations, and noting that for $n$ such that $n\geq \frac{4}{p_0^2}$ and $n\geq \frac{m^2}{144}$, 
    \begin{equation} 
    \frac{e^{\frac1{12 n+1}}}{ e^{\frac{m}{12 (np_0-\sqrt{n})}}}
 \geq\frac1{e^{\frac{m}{12 \sqrt{n}}}}\geq e^{-1},
    \end{equation} 
    we obtain that for sufficiently large values of $n$:
    \begin{equation}
         P_{\theta'}(\boldsymbol{\pi})\geq e^{E-1}m^{\frac m2}\frac1{(2\pi)^{\frac{m-1}2}}n^{-\frac{m-1}2}
    \end{equation}
    for $E=-(1+D)^2 /p_0.$ This proves part 2). 

